from pathlib import Path
p=Path('.temp/build_technical_video.py');s=p.read_text(encoding='utf-8')
s=s.replace('.agent-overview{display:grid;grid-template-columns:.9fr 1.2fr;gap:22px;margin-top:26px}', '.agent-overview{display:grid;grid-template-columns:.9fr 1.2fr;gap:22px;margin-top:20px}').replace('.agent-overview .panel{padding:21px 26px}', '.agent-overview .panel{padding:18px 26px}').replace('margin:11px 0 13px;gap:14px', 'margin:9px 0 10px;gap:14px').replace('.everyday-score>strong{font:59px', '.everyday-score>strong{font:54px').replace('gap:22px;margin-top:22px}.agent-lessons .panel{padding:22px 26px}', 'gap:22px;margin-top:20px}.agent-lessons .panel{padding:18px 26px}').replace('.agent-lessons h2{font-size:26px;margin:10px 0 14px}', '.agent-lessons h2{font-size:25px;margin:8px 0 10px}').replace('.agent-lessons p{font-size:20px;line-height:1.65}', '.agent-lessons p{font-size:19px;line-height:1.6}').replace('margin:18px 0 13px;padding:14px 17px;', 'margin:14px 0 10px;padding:12px 17px;').replace('.retest-strip strong{font-size:21px;', '.retest-strip strong{font-size:20px;').replace('.resolution .fine{font-size:16px;line-height:1.65}', '.resolution .fine{font-size:15px;line-height:1.6}').replace('color:var(--muted);margin-top:17px}', 'color:var(--muted);margin-top:15px}')
p.write_text(s,encoding='utf-8')
exec(compile(s,str(p),'exec'),{'__file__':str(p.resolve()),'__name__':'__main__'})
md=Path('.report/演示视频_20261022/05_关键技术与测试_配套讲稿.md')
with md.open('a',encoding='utf-8') as f:f.write('\n## 制作检查记录\n\n已检查页面结构、本地链接、脚本语法、240 秒预算及页内外讲稿一致性。第七页按“测试结果—问题与解决”顺序展示；当前环境尚未完成浏览器显示验收。\n')
